              'في الاحتراق غير التام (عند نقص O₂) : لا تجد كل ذرات الكربون ما يكفيها من ذرات الأكسجين، فيتحد بعضها بذرة أكسجين واحدة فقط مكونًا جزيئات أحادي أكسيد الكربون (CO)، وتتجمع ذرات كربون أخرى على شكل جسيمات صلبة سوداء هي السخام (C).',
